using BARANG.Core.Application.Abstractions.Actors;
using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Orders;
using BARANG.Core.Domain.Catalog;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.BusinessAnalysis;
using BARANG.Core.Infrastructure.Persistence;
using BARANG.Core.Application.Pricing;
using BARANG.Core.Application.Workflow;
using BARANG.Core.Infrastructure.Inventory;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage;

namespace BARANG.Core.Infrastructure.Orders;
#pragma warning disable CA1725

public sealed class OrderAdministration(CoreDbContext db, ITransactionExecutor tx, ICompanyContext company, ICurrentActor actor, IAuditWriter audit, TimeProvider time, IOrderPricingEngine pricing, IWorkflowDefinitionRuntime workflow, InventoryAdministration inventory) : IOrderAdministration
{
    private Guid Company => company.RequireCompanyId(); private Guid Actor => Guid.TryParse(actor.Actor.UserId, out Guid id) ? id : throw new InvalidOperationException("Authenticated user required."); private DateTimeOffset Now => time.GetUtcNow();
    public Task<Result<OrderView>> CreateDraftAsync(CreateDraftCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await ValidHeader(c.BranchId, c.CustomerId, t)) return Result.Failure<OrderView>(OrderErrors.InvalidCustomer); if (c.ExternalReference is not null && await db.Orders.AnyAsync(x => x.Source == c.Source && x.ExternalReference == c.ExternalReference.Trim(), t)) return Result.Failure<OrderView>(OrderErrors.DuplicateExternalReference); Result<Order> r = Order.CreateDraft(Guid.NewGuid(), Company, c.BranchId, c.CustomerId, c.Source, c.ExternalReference, c.OrderDate, c.RequestedDeliveryDate, Actor, Now); if (r.IsFailure) return Result.Failure<OrderView>(r.Error); db.Orders.Add(r.Value); Timeline(r.Value, "DraftCreated"); Log("order.draft.created", r.Value.Id); if (c.ShippingAddress is not null) { Result<OrderAddressSnapshot> a = await BuildAddress(r.Value, c.ShippingAddress, t); if (a.IsFailure) return Result.Failure<OrderView>(a.Error); db.OrderAddressSnapshots.Add(a.Value); r.Value.AttachShipping(a.Value.Id, Now); } return Result.Success(await View(r.Value, t)); }, ct);
    public Task<Result<OrderView>> GetAsync(Guid id, CancellationToken ct) => tx.ExecuteAsync(async t => { Order? x = await db.Orders.AsNoTracking().SingleOrDefaultAsync(o => o.Id == id, t); return x is null ? Result.Failure<OrderView>(OrderErrors.NotFound) : Result.Success(await View(x, t, true)); }, ct);
    public Task<Result<OrderView>> EditDraftAsync(Guid id, EditDraftCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Order? x = await db.Orders.SingleOrDefaultAsync(o => o.Id == id, t); if (x is null) return Result.Failure<OrderView>(OrderErrors.NotFound); if (x.Version != c.Version) return Result.Failure<OrderView>(OrderErrors.Concurrency); if (!await ValidHeader(c.BranchId, c.CustomerId, t)) return Result.Failure<OrderView>(OrderErrors.InvalidCustomer); Result r = x.EditDraft(c.BranchId, c.CustomerId, c.OrderDate, c.RequestedDeliveryDate, c.ExternalReference, Now); if (r.IsFailure) return Result.Failure<OrderView>(r.Error); Timeline(x, "HeaderUpdated"); Log("order.updated", id); return Result.Success(await View(x, t)); }, ct);
    public Task<Result<OrderView>> SetShippingAsync(Guid id, AddressCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Order? o = await db.Orders.SingleOrDefaultAsync(x => x.Id == id, t); if (o is null) return Result.Failure<OrderView>(OrderErrors.NotFound); if (o.Status != OrderStatus.Draft) return Result.Failure<OrderView>(OrderErrors.NotDraft); OrderAddressSnapshot? a = await db.OrderAddressSnapshots.SingleOrDefaultAsync(x => x.OrderId == id, t); if (a is null) { Result<OrderAddressSnapshot> made = await BuildAddress(o, c, t); if (made.IsFailure) return Result.Failure<OrderView>(made.Error); a = made.Value; db.Add(a); o.AttachShipping(a.Id, Now); } else { if (a.Version != c.Version) return Result.Failure<OrderView>(OrderErrors.Concurrency); Result r = a.Update(c.RecipientName, c.RecipientPhone, c.CountryCode, c.Province, c.City, c.District, c.AddressLine1, c.AddressLine2, c.PostalCode, Now); if (r.IsFailure) return Result.Failure<OrderView>(r.Error); } Timeline(o, "ShippingAddressUpdated"); Log("order.updated", id); return Result.Success(await View(o, t)); }, ct);
    public Task<Result<OrderItemView>> AddItemAsync(Guid orderId, ItemCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Order? o = await Draft(orderId, t); if (o is null) return Result.Failure<OrderItemView>(OrderErrors.NotDraft); if (!await ValidProduct(c.ProductId, c.ProductVariantId, t)) return Result.Failure<OrderItemView>(OrderErrors.InvalidVariant); int line = (await db.OrderItems.Where(x => x.OrderId == orderId).MaxAsync(x => (int?)x.LineNumber, t) ?? 0) + 1; Result<OrderItem> r = OrderItem.Create(Guid.NewGuid(), Company, orderId, line, c.ProductId, c.ProductVariantId, c.Quantity, c.Notes, Now); if (r.IsFailure) return Result.Failure<OrderItemView>(r.Error); db.Add(r.Value); Timeline(o, "ItemAdded", r.Value.Id); Log("order.item.added", r.Value.Id); return Result.Success(await ItemView(r.Value, t)); }, ct);
    public Task<Result<OrderItemView>> UpdateItemAsync(Guid orderId, Guid itemId, ItemCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { if (await Draft(orderId, t) is not Order o) return Result.Failure<OrderItemView>(OrderErrors.NotDraft); OrderItem? x = await db.OrderItems.SingleOrDefaultAsync(i => i.Id == itemId && i.OrderId == orderId, t); if (x is null) return Result.Failure<OrderItemView>(OrderErrors.NotFound); if (x.Version != c.Version) return Result.Failure<OrderItemView>(OrderErrors.Concurrency); if (x.ProductId != c.ProductId || x.ProductVariantId != c.ProductVariantId) return Result.Failure<OrderItemView>(OrderErrors.InvalidProduct); Result r = x.Update(c.Quantity, c.Notes, Now); if (r.IsFailure) return Result.Failure<OrderItemView>(r.Error); Timeline(o, "ItemUpdated", itemId); Log("order.item.updated", itemId); return Result.Success(await ItemView(x, t)); }, ct);
    public Task<Result> RemoveItemAsync(Guid orderId, Guid itemId, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { if (await Draft(orderId, t) is not Order o) return Result.Failure(OrderErrors.NotDraft); OrderItem? x = await db.OrderItems.SingleOrDefaultAsync(i => i.Id == itemId && i.OrderId == orderId, t); if (x is null) return Result.Failure(OrderErrors.NotFound); if (x.Version != version) return Result.Failure(OrderErrors.Concurrency); x.Remove(Now); foreach (OrderPrintOperation p in await db.OrderPrintOperations.Where(p => p.OrderItemId == itemId && p.IsActive).ToListAsync(t)) p.Remove(Now); Timeline(o, "ItemRemoved", itemId); Log("order.item.removed", itemId); return Result.Success(); }, ct);
    public Task<Result<OrderPrintOperationView>> AddPrintAsync(Guid orderId, Guid itemId, PrintOperationCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { if (await Draft(orderId, t) is not Order o || !await db.OrderItems.AnyAsync(x => x.Id == itemId && x.OrderId == orderId && x.IsActive, t)) return Result.Failure<OrderPrintOperationView>(OrderErrors.NotDraft); if (!await ValidPrintMethod(c.PrintMethodCode, t)) return Result.Failure<OrderPrintOperationView>(OrderErrors.InvalidPrintMethod); Result refs = await ValidReferences(c.ArtworkVersionId, c.FileVersionId, t); if (refs.IsFailure) return Result.Failure<OrderPrintOperationView>(refs.Error); Result<OrderPrintOperation> r = OrderPrintOperation.Create(Guid.NewGuid(), Company, orderId, itemId, c.Sequence, c.PrintPositionCode, c.PrintMethodCode, c.Width, c.Height, c.ArtworkVersionId, c.FileVersionId, c.Notes, Now); if (r.IsFailure) return Result.Failure<OrderPrintOperationView>(r.Error); if (await db.OrderPrintOperations.AnyAsync(x => x.OrderItemId == itemId && x.Sequence == c.Sequence && x.IsActive, t)) return Result.Failure<OrderPrintOperationView>(OrderErrors.InvalidData); db.Add(r.Value); Timeline(o, "PrintOperationAdded", r.Value.Id); Log("order.print.added", r.Value.Id); return Result.Success(PrintView(r.Value)); }, ct);
    public Task<Result<OrderPrintOperationView>> UpdatePrintAsync(Guid orderId, Guid itemId, Guid operationId, PrintOperationCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { if (await Draft(orderId, t) is not Order o) return Result.Failure<OrderPrintOperationView>(OrderErrors.NotDraft); OrderPrintOperation? x = await db.OrderPrintOperations.SingleOrDefaultAsync(p => p.Id == operationId && p.OrderItemId == itemId, t); if (x is null) return Result.Failure<OrderPrintOperationView>(OrderErrors.NotFound); if (x.Version != c.Version) return Result.Failure<OrderPrintOperationView>(OrderErrors.Concurrency); if (!await ValidPrintMethod(c.PrintMethodCode, t)) return Result.Failure<OrderPrintOperationView>(OrderErrors.InvalidPrintMethod); Result refs = await ValidReferences(c.ArtworkVersionId, c.FileVersionId, t); if (refs.IsFailure) return Result.Failure<OrderPrintOperationView>(refs.Error); Result r = x.Update(c.Sequence, c.PrintPositionCode, c.PrintMethodCode, c.Width, c.Height, c.ArtworkVersionId, c.FileVersionId, c.Notes, Now); if (r.IsFailure) return Result.Failure<OrderPrintOperationView>(r.Error); Timeline(o, "PrintOperationUpdated", x.Id); Log("order.print.updated", x.Id); return Result.Success(PrintView(x)); }, ct);
    public Task<Result> RemovePrintAsync(Guid orderId, Guid itemId, Guid operationId, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { if (await Draft(orderId, t) is not Order o) return Result.Failure(OrderErrors.NotDraft); OrderPrintOperation? x = await db.OrderPrintOperations.SingleOrDefaultAsync(p => p.Id == operationId && p.OrderItemId == itemId, t); if (x is null) return Result.Failure(OrderErrors.NotFound); if (x.Version != version) return Result.Failure(OrderErrors.Concurrency); x.Remove(Now); Timeline(o, "PrintOperationRemoved", x.Id); Log("order.print.removed", x.Id); return Result.Success(); }, ct);
    public Task<Result<IReadOnlyList<OrderValidationIssue>>> ValidateAsync(Guid id, CancellationToken ct) => tx.ExecuteAsync(async t => { Order? o = await db.Orders.AsNoTracking().SingleOrDefaultAsync(x => x.Id == id, t); if (o is null) return Result.Failure<IReadOnlyList<OrderValidationIssue>>(OrderErrors.NotFound); return Result.Success<IReadOnlyList<OrderValidationIssue>>(await Issues(o, t)); }, ct);
    public Task<Result<OrderView>> SubmitAsync(Guid id, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { Order? o = await db.Orders.SingleOrDefaultAsync(x => x.Id == id, t); if (o is null) return Result.Failure<OrderView>(OrderErrors.NotFound); if (o.Status == OrderStatus.Submitted) return Result.Success(await View(o, t)); if (o.Version != version) return Result.Failure<OrderView>(OrderErrors.Concurrency); if (o.Status != OrderStatus.Draft) return Result.Failure<OrderView>(OrderErrors.InvalidTransition); IReadOnlyList<OrderValidationIssue> issues = await Issues(o, t); if (issues.Count > 0) return Result.Failure<OrderView>(OrderErrors.Incomplete); List<OrderItem> items = await db.OrderItems.Where(x => x.OrderId == id && x.IsActive).ToListAsync(t); foreach (OrderItem item in items) { Product p = await db.Products.SingleAsync(x => x.Id == item.ProductId, t); ProductVariant v = await db.ProductVariants.SingleAsync(x => x.Id == item.ProductVariantId, t); item.Freeze(p.ProductCode, p.Name, v.Sku, v.DisplayName, v.SizeCode, v.ColorCode, p.UnitOfMeasureCode, Now); ProductTechnicalProfile? pp=await db.ProductTechnicalProfiles.AsNoTracking().SingleOrDefaultAsync(x=>x.ProductId==p.Id&&x.ProductVariantId==null,t); ProductTechnicalProfile? vp=await db.ProductTechnicalProfiles.AsNoTracking().SingleOrDefaultAsync(x=>x.ProductId==p.Id&&x.ProductVariantId==v.Id,t); db.OrderItemTechnicalSnapshots.Add(OrderItemTechnicalSnapshot.Create(Company,item.Id,pp,vp,Now)); } Result<OrderPricingView> priced = await pricing.CalculateInsideTransactionAsync(o, true, null, t); if (priced.IsFailure) return Result.Failure<OrderView>(priced.Error); await using System.Data.Common.DbCommand command = db.Database.GetDbConnection().CreateCommand(); command.CommandText = "SELECT nextval('barang.order_number_seq')"; command.Transaction = db.Database.CurrentTransaction!.GetDbTransaction(); long seq = Convert.ToInt64(await command.ExecuteScalarAsync(t), System.Globalization.CultureInfo.InvariantCulture); string number = $"ORD-{Now.Year}-{seq:0000000000}"; Result r = o.Submit(number, Now); if (r.IsFailure) return Result.Failure<OrderView>(r.Error); Result<object> started=await workflow.StartInsideTransactionAsync(o.Id,t);if(started.IsFailure)return Result.Failure<OrderView>(started.Error); Timeline(o, "Submitted"); Log("order.submitted", o.Id); Log("order.status.changed", o.Id); return Result.Success(await View(o, t)); }, ct);
    public Task<Result<OrderView>> CancelAsync(Guid id, CancelOrderCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Order? o = await db.Orders.SingleOrDefaultAsync(x => x.Id == id, t); if (o is null) return Result.Failure<OrderView>(OrderErrors.NotFound); if (o.Version != c.Version) return Result.Failure<OrderView>(OrderErrors.Concurrency); Result r = o.Cancel(c.ReasonCode, c.ReasonText, Actor, Now); if (r.IsFailure) return Result.Failure<OrderView>(r.Error); Result released = await inventory.ReleaseOrderReservationsInsideTransactionAsync(id, t); if (released.IsFailure) return Result.Failure<OrderView>(released.Error); Timeline(o, "Cancelled"); Log("order.cancelled", o.Id); Log("order.status.changed", o.Id); return Result.Success(await View(o, t)); }, ct);
    public Task<Result<OrderChangeRequestView>> CreateChangeRequestAsync(Guid id, ChangeRequestCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Order? o = await db.Orders.SingleOrDefaultAsync(x => x.Id == id, t); if (o is null) return Result.Failure<OrderChangeRequestView>(OrderErrors.NotFound); if (o.Status != OrderStatus.Submitted) return Result.Failure<OrderChangeRequestView>(OrderErrors.InvalidTransition); Result<OrderChangeRequest> r = OrderChangeRequest.Create(Company, id, Actor, c.ChangeType, c.Reason, c.RequestedChangesJson, Now); if (r.IsFailure) return Result.Failure<OrderChangeRequestView>(r.Error); db.Add(r.Value); Timeline(o, "ChangeRequested", r.Value.Id); Log("order.change_request.created", r.Value.Id); return Result.Success(ChangeView(r.Value)); }, ct);
    public Task<Result<IReadOnlyList<OrderTimelineView>>> TimelineAsync(Guid id, CancellationToken ct) => tx.ExecuteAsync(async t => await db.Orders.AnyAsync(x => x.Id == id, t) ? Result.Success<IReadOnlyList<OrderTimelineView>>((await db.OrderTimelineEvents.AsNoTracking().Where(x => x.OrderId == id).OrderBy(x => x.OccurredAtUtc).ThenBy(x => x.Id).ToListAsync(t)).Select(TimelineView).ToArray()) : Result.Failure<IReadOnlyList<OrderTimelineView>>(OrderErrors.NotFound), ct);
    public Task<Result<Page<OrderSummaryView>>> SearchAsync(OrderSearchQuery q, CancellationToken ct) => tx.ExecuteAsync(async t => { if (q.Page < 1 || q.PageSize is < 1 or > 100) return Result.Failure<Page<OrderSummaryView>>(OrderErrors.InvalidData); IQueryable<Order> query = db.Orders.AsNoTracking(); if (!string.IsNullOrWhiteSpace(q.OrderNumber)) query = query.Where(x => x.OrderNumber != null && EF.Functions.ILike(x.OrderNumber, $"%{q.OrderNumber.Trim()}%")); if (q.CustomerId is not null) query = query.Where(x => x.CustomerId == q.CustomerId); if (q.Status is not null) query = query.Where(x => x.Status == q.Status); if (q.BranchId is not null) query = query.Where(x => x.BranchId == q.BranchId); if (q.Source is not null) query = query.Where(x => x.Source == q.Source); if (q.OrderDateFrom is not null) query = query.Where(x => x.OrderDate >= q.OrderDateFrom); if (q.OrderDateTo is not null) query = query.Where(x => x.OrderDate <= q.OrderDateTo); if (q.SubmittedFrom is not null) query = query.Where(x => x.SubmittedAtUtc >= q.SubmittedFrom); if (q.SubmittedTo is not null) query = query.Where(x => x.SubmittedAtUtc <= q.SubmittedTo); if (!string.IsNullOrWhiteSpace(q.ExternalReference)) query = query.Where(x => x.ExternalReference != null && EF.Functions.ILike(x.ExternalReference, $"%{q.ExternalReference.Trim()}%")); if (!string.IsNullOrWhiteSpace(q.CustomerSearch)) { string s = q.CustomerSearch.Trim(); query = query.Where(o => db.Customers.Any(c => c.Id == o.CustomerId && (EF.Functions.ILike(c.CustomerCode, $"%{s}%") || EF.Functions.ILike(c.DisplayName, $"%{s}%")))); } long total = await query.LongCountAsync(t); var rows = await query.OrderByDescending(x => x.CreatedAtUtc).ThenByDescending(x => x.Id).Skip((q.Page - 1) * q.PageSize).Take(q.PageSize).ToListAsync(t); Dictionary<Guid, Customer> customers = await db.Customers.AsNoTracking().Where(x => rows.Select(r => r.CustomerId).Contains(x.Id)).ToDictionaryAsync(x => x.Id, t); return Result.Success(new Page<OrderSummaryView>(rows.Select(x => new OrderSummaryView(x.Id, x.OrderNumber, x.CustomerId, customers[x.CustomerId].CustomerCode, customers[x.CustomerId].DisplayName, x.BranchId, x.Status, x.Source, x.OrderDate, x.CreatedAtUtc, x.Version)).ToArray(), q.Page, q.PageSize, total)); }, ct);
    private async Task<bool> ValidHeader(Guid branch, Guid customer, CancellationToken t) => await db.Branches.AnyAsync(x => x.Id == branch && x.IsActive, t) && await db.Customers.AnyAsync(x => x.Id == customer && x.Status == CustomerStatus.Active, t); private async Task<bool> ValidProduct(Guid product, Guid variant, CancellationToken t) => await db.Products.AnyAsync(x => x.Id == product && x.IsActive, t) && await db.ProductVariants.AnyAsync(x => x.Id == variant && x.ProductId == product && x.IsActive, t); private Task<Order?> Draft(Guid id, CancellationToken t) => db.Orders.SingleOrDefaultAsync(x => x.Id == id && x.Status == OrderStatus.Draft, t);
    private async Task<bool> ValidPrintMethod(string? code, CancellationToken t) { if (string.IsNullOrWhiteSpace(code)) return true; string normalized = code.Trim().ToLowerInvariant(); return await db.LookupTypes.AnyAsync(type => type.Code == "print.method" && type.IsActive && (type.CompanyId == null || type.CompanyId == Company) && db.LookupValues.Any(value => value.LookupTypeId == type.Id && value.Code == normalized && value.IsActive && (value.CompanyId == null || value.CompanyId == Company)), t); }
    private async Task<Result> ValidReferences(Guid? a, Guid? f, CancellationToken t) { if (a is not null && !await db.ArtworkVersions.AnyAsync(x => x.Id == a, t)) return Result.Failure(OrderErrors.InvalidArtworkVersion); if (f is not null && !await db.FileVersions.AnyAsync(x => x.Id == f && !x.IsArchived, t)) return Result.Failure(OrderErrors.InvalidFileVersion); return Result.Success(); }
    private async Task<Result<OrderAddressSnapshot>> BuildAddress(Order o, AddressCommand c, CancellationToken t) { if (c.SourceCustomerAddressId is not null && !await db.CustomerAddresses.AnyAsync(x => x.Id == c.SourceCustomerAddressId && x.CustomerId == o.CustomerId && x.IsActive, t)) return Result.Failure<OrderAddressSnapshot>(OrderErrors.InvalidShippingAddress); return OrderAddressSnapshot.Create(Guid.NewGuid(), Company, o.Id, c.SourceCustomerAddressId, c.RecipientName, c.RecipientPhone, c.CountryCode, c.Province, c.City, c.District, c.AddressLine1, c.AddressLine2, c.PostalCode, Now); }
    private async Task<IReadOnlyList<OrderValidationIssue>> Issues(Order o, CancellationToken t) { List<OrderValidationIssue> x = []; if (o.Status != OrderStatus.Draft) x.Add(new("order.not_draft")); if (!await ValidHeader(o.BranchId, o.CustomerId, t)) x.Add(new("order.invalid_customer", "customerId")); List<OrderItem> items = await db.OrderItems.AsNoTracking().Where(i => i.OrderId == o.Id && i.IsActive).ToListAsync(t); if (items.Count == 0) x.Add(new("order.item_required", "items")); foreach (OrderItem i in items) if (!await ValidProduct(i.ProductId, i.ProductVariantId, t)) x.Add(new("order.invalid_product", $"items[{i.LineNumber}]")); return x; }
    private void Timeline(Order o, string type, Guid? related = null) => db.OrderTimelineEvents.Add(OrderTimelineEvent.Create(Company, o.Id, type, Actor, Now, null, related)); private void Log(string action, Guid id) => audit.Write(new(action, "order", id.ToString(), ChangeKind: AuditChangeKind.Modified));
    private async Task<OrderView> View(Order o, CancellationToken t, bool noTrack = false) { IQueryable<OrderItem> iq = db.OrderItems.Where(x => x.OrderId == o.Id); IQueryable<OrderPrintOperation> pq = db.OrderPrintOperations.Where(x => x.OrderId == o.Id); if (noTrack) { iq = iq.AsNoTracking(); pq = pq.AsNoTracking(); } List<OrderPrintOperation> prints = await pq.OrderBy(x => x.Sequence).ToListAsync(t); List<OrderItemView> items = []; foreach (OrderItem i in await iq.OrderBy(x => x.LineNumber).ToListAsync(t)) items.Add(ToItem(i, prints.Where(p => p.OrderItemId == i.Id).Select(PrintView).ToArray())); OrderAddressSnapshot? a = await db.OrderAddressSnapshots.AsNoTracking().SingleOrDefaultAsync(x => x.OrderId == o.Id, t); return new(o.Id, o.BranchId, o.CustomerId, o.OrderNumber, o.Source, o.ExternalReference, o.Status, o.OrderDate, o.RequestedDeliveryDate, o.SubmittedAtUtc, o.CancelledAtUtc, o.CancellationReasonCode, o.CancellationReasonText, o.Version, a is null ? null : AddressView(a), items); }
    private async Task<OrderItemView> ItemView(OrderItem i, CancellationToken t) => ToItem(i, (await db.OrderPrintOperations.AsNoTracking().Where(x => x.OrderItemId == i.Id).OrderBy(x => x.Sequence).ToListAsync(t)).Select(PrintView).ToArray()); private static OrderItemView ToItem(OrderItem x, IReadOnlyList<OrderPrintOperationView> p) => new(x.Id, x.LineNumber, x.ProductId, x.ProductVariantId, x.Quantity, x.Notes, x.IsActive, new(x.SnapshotProductCode, x.SnapshotProductName, x.SnapshotVariantSku, x.SnapshotVariantDisplayName, x.SnapshotSizeCode, x.SnapshotColorCode, x.SnapshotUomCode), x.Version, p); private static OrderPrintOperationView PrintView(OrderPrintOperation x) => new(x.Id, x.OrderItemId, x.Sequence, x.PrintPositionCode, x.PrintMethodCode, x.Width, x.Height, x.ArtworkVersionId, x.FileVersionId, x.Notes, x.IsActive, x.Version); private static OrderAddressView AddressView(OrderAddressSnapshot x) => new(x.Id, x.SourceCustomerAddressId, x.RecipientName, x.RecipientPhone, x.CountryCode, x.Province, x.City, x.District, x.AddressLine1, x.AddressLine2, x.PostalCode, x.Version); private static OrderTimelineView TimelineView(OrderTimelineEvent x) => new(x.Id, x.EventType, x.OccurredAtUtc, x.ActorUserId, x.Summary, x.RelatedEntityId); private static OrderChangeRequestView ChangeView(OrderChangeRequest x) => new(x.Id, x.OrderId, x.ChangeType, x.Reason, x.RequestedChangesJson, x.Status, x.Version);
}
#pragma warning restore CA1725
